const collides=(card,x,y,width,height)=>Array.from(document.querySelectorAll('.cm-zone')).some(other=>other!==card&&x<parseInt(other.style.left)+other.offsetWidth+20&&x+width+20>parseInt(other.style.left)&&y<parseInt(other.style.top)+other.offsetHeight+20&&y+height+20>parseInt(other.style.top));const save=async(card,previous)=>{notice.classList.add('show');const payload={position_x:parseInt(card.style.left),position_y:parseInt(card.style.top),width:Math.round(card.offsetWidth),height:Math.round(card.offsetHeight)};const response=await fetch(card.dataset.saveUrl,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify(payload)});if(!response.ok)Object.entries(previous).forEach(([property,value])=>card.style[property]=value+'px');notice.textContent=response.ok?@json(__('Расположение сохранено')):@json(__('Карточки не могут пересекаться'));setTimeout(()=>{notice.classList.remove('show');notice.textContent=@json(__('Сохраняем расположение…'))},1200)};
